/*
 * Solplanet Cards for Home Assistant
 * Inspired by the official Solplanet app. Built for the
 * home-assistant-solplanet integration (zbigniewmotyka / zubir2k fork).
 *
 *   type: custom:solplanet-flow-card    -> live power flow scene (day/night aware)
 *   type: custom:solplanet-stats-card   -> today's yield, consumption, self-consumption, self-sufficiency
 */

const CARD_VERSION = "1.3.0";

/* ------------------------------------------------------------------ */
/* Entity discovery                                                    */
/* ------------------------------------------------------------------ */

// Entity ids the integration creates (see custom_components/solplanet/entity.py):
//   inverter : sensor.solplanet_<isn>_<name>
//   battery  : sensor.solplanet_battery_<isn>_<name>
//   meter    : sensor.solplanet_meter_<isn>_<name>
const PATTERNS = {
  pv_power: [/^sensor\.solplanet_battery_[a-z0-9_]+_pv_power$/],
  inverter_power: [/^sensor\.solplanet_(?!battery_|meter_|submeter_)[a-z0-9]+_power$/],
  inverter_status: [/^sensor\.solplanet_(?!battery_|meter_|submeter_)[a-z0-9]+_inverter_status$/],
  grid_power: [/^sensor\.solplanet_meter_[a-z0-9_]+_grid_power$/],
  battery_power: [/^sensor\.solplanet_battery_[a-z0-9_]+_battery_power$/],
  battery_soc: [/^sensor\.solplanet_battery_[a-z0-9_]+_battery_state_of_charge$/],
  battery_status: [/^sensor\.solplanet_battery_[a-z0-9_]+_battery_status$/],
  pv_today: [
    /^sensor\.solplanet_battery_[a-z0-9_]+_pv_energy_today$/,
    /^sensor\.solplanet_(?!battery_|meter_|submeter_)[a-z0-9]+_energy_produced_today$/,
  ],
  grid_in_today: [/^sensor\.solplanet_meter_[a-z0-9_]+_grid_energy_in_today$/],
  grid_out_today: [/^sensor\.solplanet_meter_[a-z0-9_]+_grid_energy_out_today$/],
  battery_charge_total: [/^sensor\.solplanet_battery_[a-z0-9_]+_battery_energy_for_charging$/],
  battery_discharge_total: [/^sensor\.solplanet_battery_[a-z0-9_]+_battery_energy_for_discharging$/],
};

const ENTITY_KEYS = Object.keys(PATTERNS).concat([
  "load_power",
  "charger_power",
  "consumption_today",
  "battery_charge_today",
  "battery_discharge_today",
]);

function discover(hass, config) {
  const ids = Object.keys(hass.states);
  const out = {};
  for (const key of ENTITY_KEYS) {
    if (config[key]) {
      out[key] = config[key];
      continue;
    }
    const pats = PATTERNS[key];
    if (!pats) continue;
    for (const re of pats) {
      const hit = ids.find((id) => re.test(id));
      if (hit) {
        out[key] = hit;
        break;
      }
    }
  }
  return out;
}

const UNAVAILABLE = ["unavailable", "unknown", "none", ""];

function stateOf(hass, id) {
  return id && hass.states[id] ? hass.states[id] : undefined;
}

function num(hass, id) {
  const s = stateOf(hass, id);
  if (!s || UNAVAILABLE.includes(String(s.state).toLowerCase())) return null;
  const v = parseFloat(s.state);
  return Number.isFinite(v) ? v : null;
}

// Returns power in watts, honouring kW/MW units
function watts(hass, id) {
  const v = num(hass, id);
  if (v === null) return null;
  const u = (stateOf(hass, id).attributes.unit_of_measurement || "W").toLowerCase();
  if (u === "kw") return v * 1000;
  if (u === "mw") return v * 1e6;
  return v;
}

// Returns energy in kWh, honouring Wh/MWh units
function kwh(hass, id) {
  const v = num(hass, id);
  if (v === null) return null;
  const u = (stateOf(hass, id).attributes.unit_of_measurement || "kWh").toLowerCase();
  if (u === "wh") return v / 1000;
  if (u === "mwh") return v * 1000;
  return v;
}

function fmtPower(w) {
  if (w === null || w === undefined) return { v: "—", u: "" };
  const a = Math.abs(w);
  if (a >= 1000) return { v: (a / 1000).toFixed(a >= 10000 ? 2 : 3), u: "kW" };
  return { v: Math.round(a).toString(), u: "W" };
}

function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

function pad(n) {
  return String(n).padStart(2, "0");
}

function fmtStamp(d) {
  return `${pad(d.getDate())}.${pad(d.getMonth() + 1)}.${d.getFullYear()},${pad(d.getHours())}:${pad(
    d.getMinutes()
  )}:${pad(d.getSeconds())}`;
}

function fmtDuration(ms) {
  const m = Math.max(0, Math.round(ms / 60000));
  const h = Math.floor(m / 60);
  return h ? `${h}h ${m % 60}m` : `${m}m`;
}

function moreInfo(el, entityId) {
  if (!entityId) return;
  el.dispatchEvent(
    new CustomEvent("hass-more-info", { detail: { entityId }, bubbles: true, composed: true })
  );
}

function svgIcon(path, cls = "") {
  return `<svg class="mdi ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg>`;
}

/* ------------------------------------------------------------------ */
/* Time of day                                                         */
/* ------------------------------------------------------------------ */

// phase: day | dawn | dusk | night. progress: 0..1 along today's sun (or moon) arc.
function timeOfDay(hass, config) {
  const now = new Date();
  if (config.force_phase) {
    const f = config.force_phase;
    return { phase: f, progress: f === "night" ? 0.45 : f === "dawn" ? 0.06 : f === "dusk" ? 0.94 : 0.4, now };
  }
  const sun = hass.states[config.sun_entity || "sun.sun"];
  if (sun && sun.attributes && sun.attributes.next_rising && sun.attributes.next_setting) {
    const elev = Number(sun.attributes.elevation);
    const rise = new Date(sun.attributes.next_rising);
    const set = new Date(sun.attributes.next_setting);
    const up = sun.state === "above_horizon";
    let progress;
    let nextEvent;
    if (up) {
      const start = new Date(rise.getTime() - 86400000); // today's sunrise (approx.)
      progress = (now - start) / (set - start);
      nextEvent = { type: "sunset", at: set };
    } else {
      const start = new Date(set.getTime() - 86400000); // last sunset (approx.)
      progress = (now - start) / (rise - start);
      nextEvent = { type: "sunrise", at: rise };
    }
    progress = clamp(progress, 0, 1);
    let phase = up ? "day" : "night";
    if (Number.isFinite(elev) && elev > -6 && elev < 8) {
      phase = sun.attributes.rising ? "dawn" : "dusk";
    }
    return { phase, progress, now, nextEvent, elevation: elev };
  }
  // Fallback: fixed clock (06:30 sunrise, 19:30 sunset)
  const h = now.getHours() + now.getMinutes() / 60;
  const riseH = 6.5;
  const setH = 19.5;
  let phase = "night";
  if (h >= riseH - 0.4 && h < riseH + 0.8) phase = "dawn";
  else if (h >= riseH + 0.8 && h < setH - 0.8) phase = "day";
  else if (h >= setH - 0.8 && h < setH + 0.4) phase = "dusk";
  const day = h >= riseH && h < setH;
  const progress = day ? (h - riseH) / (setH - riseH) : ((h - setH + 24) % 24) / (24 - (setH - riseH));
  return { phase, progress: clamp(progress, 0, 1), now };
}

/* ------------------------------------------------------------------ */
/* Shared styles                                                       */
/* ------------------------------------------------------------------ */

const BASE_CSS = `
  :host { display:block; }
  ha-card, .card { overflow:hidden; border-radius: var(--ha-card-border-radius, 16px); }
  .mdi { width:1em; height:1em; fill:currentColor; display:inline-block; vertical-align:-0.12em; flex:none; }
  .click { cursor:pointer; }
`;

/* ------------------------------------------------------------------ */
/* Card 1: Power flow scene                                            */
